function sshConfigEntry({ alias, host, port, user }) {
	return [
		`Host ${alias}`,
		`  HostName ${host}`,
		`  User ${user}`,
		`  Port ${port}`,
		`  IdentityFile ~/.ssh/${alias}`,
		`  CertificateFile ~/.ssh/${alias}-cert.pub`,
		`  IdentitiesOnly yes`,
		`  ServerAliveInterval 30`
	].join("\n");
}

